fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    host::display::clear(0x000505);
    let mut arm: i32 = 0;
    while arm < 16 {
        let ai: i32 = (arm * 2 + t / 8) & 31;
        let sa: i32 = tab[ai];
        let ca: i32 = tab[(ai + 8) & 31];
        let mut j: i32 = 0;
        while j < 8 {
            let puls: i32 = tab[(t * 2 + j * 4 + arm * 4) & 31] * 10 / 127;
            let r: i32 = 24 + j * 22 + puls;
            let x: i32 = cx + ca * r / 127;
            let y: i32 = cy + sa * r / 127;
            let s: i32 = 3 + j;
            let c: i32 = if (arm & 1) == 0 { 0xff88cc } else { 0xffe066 };
            host::display::fill_rect(x - s / 2, y - s / 2, s, s, c);
            j = j + 1;
        }
        arm = arm + 1;
    }
    host::display::fill_rect(cx - 6, cy - 6, 12, 12, 0xffffff);
    host::display::present();
}
